#!/usr/bin/env node
/**
 * gen-postgres-baseline.mjs — 方案第 7 节：从「全部迁移跑完后的空库」生成 PostgreSQL 基线
 *
 * 输出 sql/postgres/baseline.sql：
 *   - 全部真实表（跳过 FTS5 虚拟表及其影子表、sqlite 内部表）
 *   - 布尔语义列（pass/enabled/needs_human/await_distill/mutation_verified）→ BOOLEAN
 *   - INTEGER PRIMARY KEY AUTOINCREMENT → BIGINT GENERATED BY DEFAULT AS IDENTITY
 *   - 域完整性触发器（suite_revisions 不可变、跨仓引用 ABORT 等）翻译为 plpgsql
 *   - FTS5 → pg_trgm GIN 索引（docs/experiences 检索面）
 *   - 协作表 tenant_id 落地为真正的 NOT NULL 列（SQLite 侧由触发器强制）
 *
 * 注意：不翻译 v1–v35 的过程脚本（§13.1）；本文件由脚本生成，schema 变更后需重新生成。
 */
import fs from 'node:fs'
import path from 'node:path'
import os from 'node:os'
import { fileURLToPath, pathToFileURL } from 'node:url'

const root = path.dirname(path.dirname(fileURLToPath(import.meta.url)))

const BOOLEAN_COLUMNS = new Set([
  'verify_reports.pass',
  'repositories.enabled',
  'git_remotes.enabled',
  'suite_overlay_repo_compat.enabled',
  'gate_loops.await_distill',
  'gate_loops.needs_human',
  'test_specs.mutation_verified',
])

// ── 1. 建一个全新空库并跑完全部迁移（复用 db.js 的 import 副作用）──
const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'awp-baseline-'))
process.env.AWP_DB_PATH = path.join(tmp, 'baseline.db')
const { default: db } = await import(pathToFileURL(path.join(root, 'db.js')).href)

const tables = db
  .prepare(
    `SELECT name, sql FROM sqlite_master
     WHERE type='table' AND sql IS NOT NULL AND name NOT LIKE 'sqlite_%'
       AND name NOT LIKE '%_fts%' ORDER BY name`
  )
  .all()
const indexes = db
  .prepare(
    `SELECT name, sql FROM sqlite_master
     WHERE type='index' AND sql IS NOT NULL AND name NOT LIKE '%_fts%' ORDER BY name`
  )
  .all()
const domainTriggers = db
  .prepare(
    `SELECT name, sql FROM sqlite_master WHERE type='trigger'
     AND name NOT LIKE '%tenant_not_null%' AND name NOT IN ('exp_ai','exp_ad','exp_au','doc_ai','doc_ad','doc_au')`
  )
  .all()

const maxVersion = db.prepare('SELECT MAX(version) v FROM schema_migrations').get().v

// 按外键依赖拓扑排序建表（PG 要求被引用表先建；SQLite 表名序会倒挂）
{
  const byName = new Map(tables.map((t) => [t.name, t]))
  const deps = new Map(tables.map((t) => [t.name, new Set()]))
  for (const t of tables) {
    const fks = db.prepare('PRAGMA foreign_key_list(' + t.name + ')').all()
    for (const fk of fks) {
      if (fk.table !== t.name && byName.has(fk.table)) deps.get(t.name).add(fk.table)
    }
  }
  const ordered = []
  const state = new Map() // 0=未访问 1=访问中 2=完成
  const visit = (name, stack) => {
    if (state.get(name) === 2) return
    if (state.get(name) === 1) throw new Error('外键循环依赖: ' + [...stack, name].join(' -> '))
    state.set(name, 1)
    for (const d of deps.get(name)) visit(d, [...stack, name])
    state.set(name, 2)
    ordered.push(byName.get(name))
  }
  for (const t of tables) visit(t.name, [])
  tables.length = 0
  tables.push(...ordered)
}

function translateTable(sql, tableName) {
  let s = sql
  // 协作表 tenant_id：SQLite 侧由 ALTER 加列（可空）+ 触发器强制；基线落地为真正的 NOT NULL（方案决定 1）
  if (['tasks', 'task_versions', 'docs', 'docs_versions', 'experiences', 'verify_reports', 'gate_loops', 'task_sessions'].includes(tableName)) {
    s = s.replace(/(\btenant_id\s+TEXT)(?!\s+NOT\s+NULL)/gi, '$1 NOT NULL')
  }
  // AUTOINCREMENT 主键
  s = s.replace(
    /INTEGER PRIMARY KEY AUTOINCREMENT/gi,
    'BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY'
  )
  // 布尔语义列（行级）：应用层全链路用 0/1（与 sqlite 同构），落地为 SMALLINT 而非 BOOLEAN
  // ——BOOLEAN 会导致 "column is of type boolean but expression is of type integer"（§13.1 收口）
  for (const qualified of BOOLEAN_COLUMNS) {
    const col = qualified.split('.')[1]
    const re = new RegExp(`(\\b${col}\\s+)INTEGER\\b([^\\n]*)`, 'gi')
    s = s.replace(re, (_m, head, rest) => `${head}SMALLINT${rest}`)
  }
  // 类型映射
  s = s.replace(/\bINTEGER\b/g, 'BIGINT')
  s = s.replace(/\bREAL\b/g, 'DOUBLE PRECISION')
  return s
}

function translateIndex(sql) {
  return sql.replace(/\bINTEGER\b/g, 'BIGINT').replace(/\bREAL\b/g, 'DOUBLE PRECISION')
}

const out = []
out.push(`-- sql/postgres/baseline.sql`)
out.push(`-- 方案第 7 节：SQLite 全部迁移（v1–v${maxVersion}）跑完后的最终结构基线（含第 1–5 节列）。`)
out.push(`-- 由 scripts/gen-postgres-baseline.mjs 生成；不要手工编辑 schema，变更后重新生成。`)
out.push(`-- 布尔语义列落地为 SMALLINT 0/1（与 sqlite/应用层同构；导入不做类型转换）。`)
out.push(`-- 时间列保持 TEXT ISO，不改 timestamptz（§13.1）。`)
out.push(`-- tenant_id 为真正的 NOT NULL 列（SQLite 侧由触发器强制，此处落地列约束）。`)
out.push(`-- postgres_baseline 登记由 db/postgres-baseline.js 写入（版本 = MAX(非基线 version)+1，不在此硬编码）。`)
out.push('')
out.push('BEGIN;')
out.push('')

for (const t of tables) {
  out.push(translateTable(t.sql, t.name) + ';')
  out.push('')
}
for (const i of indexes) {
  if (/sqlite_autoindex/i.test(i.name)) continue
  out.push(translateIndex(i.sql) + ';')
}
out.push('')

// ── 2. pg_trgm GIN 全文索引（替代 FTS5，§13.1）──
out.push('-- ── 全文索引：pg_trgm GIN（替代 SQLite FTS5 虚拟表）──')
out.push('CREATE EXTENSION IF NOT EXISTS pg_trgm;')
out.push('CREATE INDEX IF NOT EXISTS idx_docs_content_trgm ON docs USING GIN (content gin_trgm_ops);')
out.push('CREATE INDEX IF NOT EXISTS idx_docs_name_trgm ON docs USING GIN (name gin_trgm_ops);')
out.push('CREATE INDEX IF NOT EXISTS idx_experiences_content_trgm ON experiences USING GIN (content gin_trgm_ops);')
out.push('CREATE INDEX IF NOT EXISTS idx_experiences_module_trgm ON experiences USING GIN (module gin_trgm_ops);')
out.push('CREATE INDEX IF NOT EXISTS idx_experiences_tags_trgm ON experiences USING GIN (tags gin_trgm_ops);')
out.push('')

// ── 3. 域完整性触发器（SQLite RAISE(ABORT) → plpgsql EXCEPTION）──
out.push('-- ── 域完整性触发器（SQLite 触发器的 PostgreSQL 等价物）──')
out.push(`
CREATE OR REPLACE FUNCTION trg_suite_revisions_immutable_fn() RETURNS trigger AS $$
BEGIN
  IF NEW.tree_oid IS DISTINCT FROM OLD.tree_oid
     OR NEW.content_sha256 IS DISTINCT FROM OLD.content_sha256
     OR NEW.manifest_sha256 IS DISTINCT FROM OLD.manifest_sha256
     OR NEW.manifest_json IS DISTINCT FROM OLD.manifest_json
     OR NEW.source_kind IS DISTINCT FROM OLD.source_kind
     OR NEW.source_commit_oid IS DISTINCT FROM OLD.source_commit_oid
     OR NEW.source_tree_path IS DISTINCT FROM OLD.source_tree_path
     OR NEW.registry_commit_oid IS DISTINCT FROM OLD.registry_commit_oid THEN
    RAISE EXCEPTION 'SUITE_REVOKED';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_suite_revisions_immutable BEFORE UPDATE ON suite_revisions
  FOR EACH ROW EXECUTE FUNCTION trg_suite_revisions_immutable_fn();
`.trim())
out.push('')

const sameRepoGuards = [
  {
    name: 'business_snapshots',
    event: 'INSERT OR UPDATE',
    checks: ['source_remote_id', 'target_remote_id'],
    lookup: 'git_remotes',
    key: 'remote_id',
  },
  {
    name: 'suite_plans',
    event: 'INSERT OR UPDATE',
    checks: ['task_instance_id'],
    lookup: 'task_instances',
    key: 'task_instance_id',
  },
  {
    name: 'test_bindings',
    event: 'INSERT OR UPDATE',
    checks: ['snapshot_id', 'suite_plan_id', 'task_instance_id'],
    lookupBy: {
      snapshot_id: { table: 'business_snapshots', key: 'snapshot_id' },
      suite_plan_id: { table: 'suite_plans', key: 'suite_plan_id' },
      task_instance_id: { table: 'task_instances', key: 'task_instance_id' },
    },
  },
]

// business_snapshots / suite_plans
out.push(`
CREATE OR REPLACE FUNCTION trg_snapshot_same_repo_fn() RETURNS trigger AS $$
BEGIN
  IF (SELECT repo_id FROM git_remotes WHERE remote_id = NEW.source_remote_id) IS DISTINCT FROM NEW.repo_id
     OR (SELECT repo_id FROM git_remotes WHERE remote_id = NEW.target_remote_id) IS DISTINCT FROM NEW.repo_id THEN
    RAISE EXCEPTION 'CROSS_REPO_REFERENCE';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_snapshot_same_repo BEFORE INSERT ON business_snapshots
  FOR EACH ROW EXECUTE FUNCTION trg_snapshot_same_repo_fn();
`.trim())
out.push('')
out.push(`
CREATE OR REPLACE FUNCTION trg_plan_same_repo_fn() RETURNS trigger AS $$
BEGIN
  IF (SELECT repo_id FROM task_instances WHERE task_instance_id = NEW.task_instance_id) IS DISTINCT FROM NEW.repo_id THEN
    RAISE EXCEPTION 'CROSS_REPO_REFERENCE';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_plan_same_repo BEFORE INSERT ON suite_plans
  FOR EACH ROW EXECUTE FUNCTION trg_plan_same_repo_fn();
`.trim())
out.push('')

// test_bindings：三个引用逐一校验
const bindingChecks = `
  IF (SELECT repo_id FROM business_snapshots WHERE snapshot_id = NEW.snapshot_id) IS DISTINCT FROM NEW.repo_id
     OR (SELECT repo_id FROM suite_plans WHERE suite_plan_id = NEW.suite_plan_id) IS DISTINCT FROM NEW.repo_id
     OR (SELECT repo_id FROM task_instances WHERE task_instance_id = NEW.task_instance_id) IS DISTINCT FROM NEW.repo_id THEN
    RAISE EXCEPTION 'CROSS_REPO_REFERENCE';
  END IF;`
out.push(`
CREATE OR REPLACE FUNCTION trg_binding_same_repo_fn() RETURNS trigger AS $$
BEGIN${bindingChecks}
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_binding_same_repo BEFORE INSERT ON test_bindings
  FOR EACH ROW EXECUTE FUNCTION trg_binding_same_repo_fn();
`.trim())
out.push('')

out.push(`
CREATE OR REPLACE FUNCTION trg_waiver_same_repo_fn() RETURNS trigger AS $$
BEGIN
  IF NEW.task_instance_id IS NOT NULL
     AND (SELECT repo_id FROM task_instances WHERE task_instance_id = NEW.task_instance_id) IS DISTINCT FROM NEW.repo_id THEN
    RAISE EXCEPTION 'CROSS_REPO_REFERENCE';
  END IF;
  IF (SELECT o.layer FROM suite_revisions r JOIN suite_overlays o ON o.overlay_id = r.overlay_id
      WHERE r.suite_revision_id = NEW.base_suite_revision_id) = 'repo'
     AND (SELECT o.repo_id FROM suite_revisions r JOIN suite_overlays o ON o.overlay_id = r.overlay_id
      WHERE r.suite_revision_id = NEW.base_suite_revision_id) IS DISTINCT FROM NEW.repo_id THEN
    RAISE EXCEPTION 'CROSS_REPO_REFERENCE';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_waiver_same_repo BEFORE INSERT ON suite_waivers
  FOR EACH ROW EXECUTE FUNCTION trg_waiver_same_repo_fn();
`.trim())
out.push('')

out.push(`
CREATE OR REPLACE FUNCTION trg_promotion_review_not_author_fn() RETURNS trigger AS $$
DECLARE proposal_author TEXT;
BEGIN
  SELECT author_principal_id INTO proposal_author FROM promotion_proposals WHERE proposal_id = NEW.proposal_id;
  IF proposal_author IS NOT DISTINCT FROM NEW.reviewer_principal_id THEN
    RAISE EXCEPTION 'PROMOTION_REVIEW_SELF_FORBIDDEN';
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;
CREATE TRIGGER trg_promotion_review_not_author BEFORE INSERT ON promotion_reviews
  FOR EACH ROW EXECUTE FUNCTION trg_promotion_review_not_author_fn();
`.trim())
out.push('')

// 校验：waiver / promotion 触发器引用的列是否存在（防生成期抄错）
for (const [table, cols] of [
  ['suite_waivers', ['task_instance_id', 'repo_id', 'base_suite_revision_id']],
  ['promotion_reviews', ['proposal_id', 'reviewer_principal_id']],
  ['promotion_proposals', ['author_principal_id']],
  ['test_bindings', ['snapshot_id', 'suite_plan_id', 'task_instance_id', 'repo_id']],
]) {
  const real = db.prepare(`PRAGMA table_info(${table})`).all().map((c) => c.name)
  for (const c of cols) {
    if (!real.includes(c)) {
      throw new Error(`触发器校验失败：${table}.${c} 不存在；请人工核对域触发器翻译`)
    }
  }
}

fs.mkdirSync(path.join(root, 'sql', 'postgres'), { recursive: true })
fs.writeFileSync(path.join(root, 'sql', 'postgres', 'baseline.sql'), out.join('\n'))
console.log(`baseline.sql 生成完成：${tables.length} 表 / ${indexes.length} 索引 / sqlite max version=${maxVersion} → postgres_baseline=${maxVersion + 1}`)
